sys_script_include.script:
var SGCeburuEncryptionUtil = Class.create();
SGCeburuEncryptionUtil.prototype = {
    initialize: function() {
    },

	convertToBase64: function(myHexString) {
		var hexArray = myHexString.toString()
			.replace(/\r|\n/g, "")
			.replace(/([\da-fA-F]{2}) ?/g, "0x$1 ")
			.replace(/ +$/, "")
			.split(" ");
		var byteString = String.fromCharCode.apply(null, hexArray);
		var base64string = this.btoa(byteString);
		return base64string;
	},

	btoa: function(bin) {
		var tableStr = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
		var table = tableStr.split("");
		for (var i = 0, j = 0, len = bin.length / 3, base64 = []; i < len; ++i) {
			var a = bin.charCodeAt(j++),
				b = bin.charCodeAt(j++),
				c = bin.charCodeAt(j++);
			if ((a | b | c) > 255) throw new Error("String contains an invalid character");
			base64[base64.length] = table[a >> 2] + table[((a << 4) & 63) | (b >> 4)] +
				(isNaN(b) ? "=" : table[((b << 2) & 63) | (c >> 6)]) +
				(isNaN(b + c) ? "=" : table[c & 63]);
		}
		return base64.join("");
	},

    type: 'SGCeburuEncryptionUtil'
};
